{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "oPvz_te0a07uow5ai4V1sw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a cracked map under the ruined gate.",
      "visual_description": "A crumbling stone gate arch, old royal banners tattered in the wind, Mara the Cartographer tracing a route with ink-stained fingers.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver peers into a broken window.",
      "visual_description": "Glass Diver kneeling before a shattered shop window, reflection of the ruined street rippling in the shards, diving helmet gleaming.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp flickers a warning on the bridge.",
      "visual_description": "Old stone bridge over a dry moat, Oracle Lamp's flame eye pulsing orange, shadows of patrols moving beyond.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scurries past armored patrols.",
      "visual_description": "Tin Fox darting between crumbling pillars, clockwork legs silent, blue glass eyes tracking the patrols' route.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Sleeping Tax Collector naps on a ledger stack.",
      "visual_description": "Pile of stamped papers and dusty ledgers in a roofless hall, Tax Collector snoring with a ledger pillow, papers stuck to sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a cursed tower on her map.",
      "visual_description": "Twisted tower leaning against a broken sky, Mara drawing a spiral symbol, ink dripping from her compass point.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver swims through a window into the tower.",
      "visual_description": "Glass Diver pressing against a dark window, reflection dissolving into liquid silver, coat shimmering as he passes through.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp illuminates a magic door.",
      "visual_description": "Ornate door with glowing runes, Oracle Lamp held high, flame casting shifting symbols on the stone floor.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox sniffs a rumored dragon scale.",
      "visual_description": "Tin Fox nose-to-scale with a large discarded scale lying in rubble, blue eyes reflecting the scale's iridescence.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector stirs as a patrol passes.",
      "visual_description": "Tax Collector half-opening one eye, armored footsteps echoing nearby, papers rustling as he shifts.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Mara deciphers the tower's curse pattern.",
      "visual_description": "Mara standing in a circle of chalk on the tower floor, compass needle spinning, faces of trapped townsfolk pressed against translucent walls.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver reaches the trapped townsfolk.",
      "visual_description": "Glass Diver emerging from a mirror inside the tower, reaching out to a group of frightened people huddled in a glassy cage.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp warns of the tower's collapse.",
      "visual_description": "Oracle Lamp flickering violently, flame eye wide, cracks spidering up the tower walls, dust falling.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox leads the escape route.",
      "visual_description": "Tin Fox racing down spiral stairs, tail key-winding, blue eyes glowing as a path through rubble.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Sleeping Tax Collector blocks the door with his ledger pile.",
      "visual_description": "Tax Collector pushing a stack of ledgers against a heavy door, papers flying, half-asleep but determined.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The group crosses the bridge under patrol fire.",
      "visual_description": "Old bridge crowded with escaping townsfolk, Glass Diver shielding them with a mirror, patrol bolts sparking off stone.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "Mara collapses the bridge behind them.",
      "visual_description": "Mara striking the bridge keystone with her compass, bridge crumbling into the moat, patrols halted on the far side.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "Oracle Lamp's flame steadies as dawn breaks.",
      "visual_description": "Group standing on safe ground, Oracle Lamp's flame calm and bright, sunrise over the ruined city, old royal banners burning in the distance.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

